def install(apps, schema_editor):
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute(FORWARD, params=None)
        for sql in changed_functions().values():
            schema_editor.execute(sql, params=None)


def uninstall(apps, schema_editor):
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute(
            """DO $$ BEGIN
          IF EXISTS (SELECT 1 FROM custody_mpcsolanatokenprovision)
             OR EXISTS (SELECT 1 FROM custody_mpcsolanatokenpublication)
             OR EXISTS (SELECT 1 FROM custody_mpcsolanadepositprovenance
                        WHERE source_owner_address IS NOT NULL)
             OR EXISTS (SELECT 1 FROM custody_mpcsolanafinancialwallet f
               JOIN custody_mpcsolanaclaim c ON c.reservation_id=f.claim_id
               WHERE c.statement->'asset'->>'kind'='ClassicToken') THEN
            RAISE EXCEPTION 'classic financial history cannot be downgraded'; END IF;
        END $$;""",
            params=None,
        )
        for sql in ORIGINAL.values():
            schema_editor.execute(sql, params=None)
        for table, trigger in [
            ("custody_ledgertransaction", "custody_sol_token_cost_birth"),
            ("custody_mpcsolanafinancialwallet", "custody_sol_token_membership_consistent"),
            ("custody_mpcsolanatokenpublication", "custody_sol_token_publication_consistent"),
            ("custody_mpcsolanatokenpublication", "custody_sol_token_publication_identity"),
            ("custody_mpcsolanatokenprovision", "custody_sol_token_parent_consistent"),
            ("custody_mpcsolanatokenprovision", "custody_sol_token_parent_identity"),
        ]:
            schema_editor.execute(f"DROP TRIGGER {trigger} ON {table}", params=None)
        for function in [
            "custody_sol_token_publication_consistent()",
            "custody_sol_token_publication_guard()",
            "custody_sol_token_parent_consistent()",
            "custody_sol_token_parent_guard()",
            "custody_sol_fin_rent_shape(jsonb,custody_mpcsolanafinancialoperation)",
            "custody_sol_fin_action(jsonb,custody_mpcsolanafinancialoperation)",
            "custody_sol_token_operation_birth(custody_mpcsolanafinancialoperation)",
            "custody_sol_token_cost_birth()",
            "custody_sol_token_costs_consistent(bigint)",
            "custody_sol_token_cost_identity(custody_ledgertransaction)",
            "custody_sol_base58_pubkey(text)",
        ]:
            schema_editor.execute("DROP FUNCTION " + function, params=None)


def preflight(apps, schema_editor):
    # PROVISION was not a protected financial subtype before this migration.
    # Never reinterpret an older generic attempt as a zero-principal initializer.
    if (
        apps.get_model("custody", "OnchainTransactionAttempt")
        .objects.filter(operation_type="PROVISION")
        .exists()
    ):
        raise RuntimeError(
            "legacy PROVISION attempts require explicit reconciliation before migration"
        )


